-- Phase 2 runtime tables. This migration is additive and preserves legacy User/Post data.
CREATE TABLE "LocalProfile" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT, "workspaceRoot" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "ProjectRecord" ("id" TEXT NOT NULL PRIMARY KEY, "profileId" TEXT NOT NULL, "name" TEXT NOT NULL, "directory" TEXT NOT NULL, "instructions" TEXT NOT NULL DEFAULT '', "memory" TEXT NOT NULL DEFAULT '', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "ProjectRecord_profileId_fkey" FOREIGN KEY ("profileId") REFERENCES "LocalProfile" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "ConversationRecord" ("id" TEXT NOT NULL PRIMARY KEY, "projectId" TEXT, "title" TEXT NOT NULL DEFAULT '', "modelId" TEXT NOT NULL DEFAULT '', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "ConversationRecord_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "ProjectRecord" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "MessageRecord" ("id" TEXT NOT NULL PRIMARY KEY, "conversationId" TEXT NOT NULL, "role" TEXT NOT NULL, "content" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "MessageRecord_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "ConversationRecord" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "ProviderRecord" ("id" TEXT NOT NULL PRIMARY KEY, "profileId" TEXT NOT NULL, "name" TEXT NOT NULL, "type" TEXT NOT NULL, "baseUrl" TEXT NOT NULL, "encryptedKey" TEXT, "enabled" BOOLEAN NOT NULL DEFAULT true, "capabilities" TEXT NOT NULL DEFAULT '{}', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "ProviderRecord_profileId_fkey" FOREIGN KEY ("profileId") REFERENCES "LocalProfile" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "ExecutionRecord" ("id" TEXT NOT NULL PRIMARY KEY, "profileId" TEXT NOT NULL, "projectId" TEXT, "status" TEXT NOT NULL, "request" TEXT NOT NULL, "events" TEXT NOT NULL DEFAULT '[]', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" DATETIME, CONSTRAINT "ExecutionRecord_profileId_fkey" FOREIGN KEY ("profileId") REFERENCES "LocalProfile" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "ExecutionEventRecord" ("id" TEXT NOT NULL PRIMARY KEY, "executionId" TEXT NOT NULL, "type" TEXT NOT NULL, "payload" TEXT NOT NULL, "sequence" INTEGER NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ExecutionEventRecord_executionId_fkey" FOREIGN KEY ("executionId") REFERENCES "ExecutionRecord" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "ApprovalRecord" ("id" TEXT NOT NULL PRIMARY KEY, "executionId" TEXT, "level" TEXT NOT NULL, "action" TEXT NOT NULL, "input" TEXT NOT NULL, "status" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "resolvedAt" DATETIME);
CREATE TABLE "FileChangeRecord" ("id" TEXT NOT NULL PRIMARY KEY, "projectId" TEXT NOT NULL, "executionId" TEXT, "tool" TEXT NOT NULL DEFAULT 'write_file', "approvalId" TEXT, "groupId" TEXT, "path" TEXT NOT NULL, "status" TEXT NOT NULL, "beforeHash" TEXT, "afterHash" TEXT, "originalSnapshot" TEXT, "modifiedSnapshot" TEXT, "diff" TEXT NOT NULL, "operationStatus" TEXT NOT NULL DEFAULT 'committed', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "FileChangeRecord_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "ProjectRecord" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "TaskRecord" ("id" TEXT NOT NULL PRIMARY KEY, "profileId" TEXT NOT NULL, "projectId" TEXT, "name" TEXT NOT NULL, "definition" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'pending', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "ArtifactRecord" ("id" TEXT NOT NULL PRIMARY KEY, "executionId" TEXT, "projectId" TEXT, "name" TEXT NOT NULL, "type" TEXT NOT NULL, "path" TEXT, "metadata" TEXT NOT NULL DEFAULT '{}', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "MigrationRecord" ("id" TEXT NOT NULL PRIMARY KEY, "source" TEXT NOT NULL, "version" TEXT NOT NULL, "status" TEXT NOT NULL, "report" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" DATETIME);
CREATE INDEX "ProjectRecord_profileId_idx" ON "ProjectRecord"("profileId");
CREATE INDEX "ConversationRecord_projectId_idx" ON "ConversationRecord"("projectId");
CREATE INDEX "MessageRecord_conversationId_createdAt_idx" ON "MessageRecord"("conversationId", "createdAt");
CREATE INDEX "ProviderRecord_profileId_idx" ON "ProviderRecord"("profileId");
CREATE INDEX "ExecutionRecord_profileId_createdAt_idx" ON "ExecutionRecord"("profileId", "createdAt");
CREATE INDEX "ExecutionEventRecord_executionId_createdAt_idx" ON "ExecutionEventRecord"("executionId", "createdAt");
CREATE UNIQUE INDEX "ExecutionEventRecord_executionId_sequence_key" ON "ExecutionEventRecord"("executionId", "sequence");
CREATE INDEX "ApprovalRecord_executionId_status_idx" ON "ApprovalRecord"("executionId", "status");
CREATE INDEX "FileChangeRecord_projectId_createdAt_idx" ON "FileChangeRecord"("projectId", "createdAt");
CREATE INDEX "TaskRecord_profileId_updatedAt_idx" ON "TaskRecord"("profileId", "updatedAt");
CREATE INDEX "ArtifactRecord_executionId_createdAt_idx" ON "ArtifactRecord"("executionId", "createdAt");
CREATE INDEX "ArtifactRecord_projectId_createdAt_idx" ON "ArtifactRecord"("projectId", "createdAt");
CREATE UNIQUE INDEX "MigrationRecord_source_version_key" ON "MigrationRecord"("source", "version");
